// Some portions generated by Claude
/** Statements about statements (RDF 1.2 triple terms as objects) in the explorer's graph. */
import { curveMidpoint } from "./edge-hit.ts";
import type { Binding, SparqlValue } from "./explorer-types.ts";
import { compactTerm, findBindingValue, isSafeSparqlIri, predicateLabel, termKind, tripleEdgeId } from "./graph-terms.ts";
import type { EdgeCurve, Graph, GraphNode, StatementLink } from "./graph-types.ts";
import { isSparqlTerm, sparqlNodeId, type SparqlTerm } from "./rdf-terms.ts";

type TripleValue = { type: "triple"; value: { subject?: unknown; predicate?: unknown; object?: unknown } };

/**
 * Id prefix of the springs the layout gets for a statement link (reifier → subject, reifier → object). They pull a
 * reifier next to the statement it describes; they are not drawn, so routing, lanes and ports must ignore them.
 */
export const STATEMENT_LINK_EDGE_PREFIX = "statement-link:";
export const isStatementLinkEdge = (edge: { id: string }) => edge.id.startsWith(STATEMENT_LINK_EDGE_PREFIX);
export type FoundStatementLink = { link: StatementLink; source: SparqlValue };

function isTriple(value: unknown): value is TripleValue {
  return Boolean(value && typeof value === "object" && (value as { type?: unknown }).type === "triple" && (value as TripleValue).value);
}

/** A term inside a triple term, when the graph can hold it (an IRI, blank node or literal; not a nested triple). */
function plainTerm(value: unknown): SparqlTerm | null {
  if (!isSparqlTerm(value)) return null;
  if (value.type === "uri" && !isSafeSparqlIri(value.value)) return null;
  return value as SparqlTerm;
}

/** The rows of a result whose object is a triple term, as statement links (`?source ?predicate <<( s p o )>>`). */
export function statementLinksOf(bindings: readonly Binding[]): FoundStatementLink[] {
  return bindings.flatMap((binding) => {
    const row = binding as Record<string, unknown>;
    const source = findBindingValue(binding, ["source", "s", "subject"]);
    const predicate = findBindingValue(binding, ["predicate", "p"]);
    const target = row.target ?? row.o ?? row.object;
    if (!source || source.type === "literal" || predicate?.type !== "uri" || !isSafeSparqlIri(predicate.value) || !isTriple(target)) return [];
    if (source.type === "uri" && !isSafeSparqlIri(source.value)) return [];
    const subject = plainTerm(target.value.subject);
    const statementPredicate = plainTerm(target.value.predicate);
    const object = plainTerm(target.value.object);
    if (!subject || subject.type === "literal" || statementPredicate?.type !== "uri" || !object) return [];
    const sourceId = sparqlNodeId(source as SparqlTerm);
    const subjectId = sparqlNodeId(subject);
    const objectId = sparqlNodeId(object);
    const link: StatementLink = {
      id: JSON.stringify([sourceId, predicate.value, subjectId, statementPredicate.value, objectId]),
      source: sourceId,
      predicate: predicate.value,
      label: predicateLabel(predicate.value),
      subject: subjectId,
      statementPredicate: statementPredicate.value,
      object: objectId,
      statementEdgeId: tripleEdgeId(subjectId, statementPredicate.value, objectId),
    };
    return [{ link, source }];
  });
}

/** Adds the links (each once) and the nodes they start from; the graph is returned unchanged when nothing is new. */
export function mergeStatementLinks(graph: Graph, found: readonly FoundStatementLink[], batchId?: string): Graph {
  const known = new Set((graph.statementLinks ?? []).map((link) => link.id));
  const fresh = found.filter(({ link }) => !known.has(link.id) && known.add(link.id));
  if (!fresh.length) return graph;
  const nodeIds = new Set(graph.nodes.map((node) => node.id));
  const nodes = [...graph.nodes];
  for (const { link, source } of fresh) {
    if (nodeIds.has(link.source)) continue;
    nodeIds.add(link.source);
    nodes.push({
      id: link.source,
      label: compactTerm(source.value),
      kind: termKind(source),
      termValue: source.value,
      x: 180 + (nodes.length % 4) * 180,
      y: 170 + Math.floor(nodes.length / 4) * 120,
    });
  }
  return {
    ...graph,
    nodes,
    statementLinks: [...(graph.statementLinks ?? []), ...fresh.map(({ link }) => ({ ...link, ...(batchId ? { batchId } : {}) }))],
    revision: graph.revision + 1,
  };
}

/** The connector of a link: from its source node to the middle of its statement's edge; null unless both are drawn. */
export function statementConnector(
  link: StatementLink,
  nodeById: ReadonlyMap<string, GraphNode>,
  curves: ReadonlyMap<string, EdgeCurve>,
) {
  const source = nodeById.get(link.source);
  const curve = curves.get(link.statementEdgeId);
  if (!curve || source?.x === undefined || source.y === undefined) return null;
  const start = { x: source.x, y: source.y };
  const end = curveMidpoint(curve);
  const round = (value: number) => Math.round(value * 10) / 10;
  return {
    path: `M${round(start.x)},${round(start.y)} L${round(end.x)},${round(end.y)}`,
    start,
    control: { x: (start.x + end.x) / 2, y: (start.y + end.y) / 2 },
    end,
  } satisfies EdgeCurve;
}
